data class UserInfo(val name: String, val age: Int)

@Composable
fun UserCard(user: UserInfo) {
    Text(text = user.name)
}

// 使用处
val user = remember { UserInfo("Alice", 25) }
UserCard(user = user)

// ❌ 错误示例：在回调中使用 LaunchedEffect
Button(onClick = {
    LaunchedEffect(Unit) {
        // 编译错误！LaunchedEffect 只能在 Composable 顶层调用
        viewModel.loadData()
    }
})

// ✅ 正确做法
val scope = rememberCoroutineScope()
Button(onClick = {
    scope.launch {
        viewModel.loadData()
    }
})

// 方案A：状态在子组件内部（耦合）
@Composable
fun SearchScreen(viewModel: SearchViewModel) {
    SearchBar() // 内部管理搜索文字
    ResultList() // 内部管理列表数据
}

// 方案B：状态提升（推荐）
@Composable
fun SearchScreen(viewModel: SearchViewModel) {
    val query by viewModel.query.collectAsState()
    val results by viewModel.results.collectAsState()

    SearchBar(
        query = query,
        onQueryChange = { viewModel.updateQuery(it) }
    )
    ResultList(results = results)
}
